import { cancelBillingSubscription } from "@/lib/billing/cancel";
import {
  billingHttpError,
  billingSessionUser,
  limitBillingRequest,
  privateBillingHeaders,
  requireBillingOrigin,
} from "@/lib/billing/http";

export const runtime = "nodejs";
export async function POST(request: Request) {
  try {
    const userId = await billingSessionUser();
    requireBillingOrigin(request);
    await limitBillingRequest(userId, "cancel");
    const body = await request.text();
    if (body.length > 4096)
      return new Response(null, {
        status: 413,
        headers: privateBillingHeaders,
      });
    let input: unknown;
    try {
      input = JSON.parse(body);
    } catch {
      return Response.json(
        { error: "Invalid cancellation request." },
        { status: 400, headers: privateBillingHeaders },
      );
    }
    return Response.json(await cancelBillingSubscription(userId, input), {
      headers: privateBillingHeaders,
    });
  } catch (error) {
    return billingHttpError(error);
  }
}
